    { izvorno: "Where is the loo?", izgovor: "wair iz thuh LOO", hr: "Where is the restroom?" },
    { izvorno: "Mind the gap", izgovor: "mynd thuh GAP", hr: "Watch the gap (the warning on the London Underground)" },
    { izvorno: "Diolch", izgovor: "DEE-olkh", hr: "Thank you (Welsh)" },
    { izvorno: "Slàinte mhath", izgovor: "SLAHN-juh VAH", hr: "Cheers, literally: good health (Scottish Gaelic)" }
